INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d1d2d3d4-4406-4000-8000-000000000006', 'b1b2c3d4-4444-4000-8000-000000000004', 6, 'Quiz: Teologia do Corpo', 'Teste seus conhecimentos', '{"questions": [{"q": "Quantas audi\u00eancias S\u00e3o Jo\u00e3o Paulo II dedicou \u00e0 Teologia do Corpo?", "correct": 2, "options": ["50", "89", "129", "200"]}, {"q": "Qual \u00e9 o conceito central da Teologia do Corpo?", "correct": 1, "options": ["A proibi\u00e7\u00e3o do prazer", "O significado esponsal do corpo", "A superioridade da alma", "A rejei\u00e7\u00e3o da mat\u00e9ria"]}, {"q": "O que a ''nudez original'' (Gn 2,25) significa teologicamente?", "correct": 1, "options": ["Pobreza material", "Pureza do olhar antes do pecado", "Aus\u00eancia de roupas", "Ingenuidade"]}]}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;